//! Durable, bounded simulation evidence. Calculation input and pages stay auditable.
use super::{simulation::LedgerEvent,quant::content_hash};
use anyhow::{Result,Context,ensure};
use serde::Serialize;
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{fs,path::{Path,PathBuf},sync::Mutex,io::{Read,Write,BufWriter,BufReader,BufRead}};
mod build_inputs{include!(concat!(env!("OUT_DIR"),"/backend_build_inputs.rs"));}
pub fn backend_build_config()->&'static str{build_inputs::BACKEND_BUILD_CONFIG}
pub fn backend_build_fingerprint()->String{
 static HASH:std::sync::LazyLock<String>=std::sync::LazyLock::new(||{let mut hash=Sha256::new();hash.update(build_inputs::BACKEND_BUILD_CONFIG.as_bytes());for(name,source)in build_inputs::BACKEND_BUILD_INPUTS{hash.update((name.len() as u64).to_be_bytes());hash.update(name.as_bytes());hash.update((source.len() as u64).to_be_bytes());hash.update(source);}hex::encode(hash.finalize())});HASH.clone()
}
pub const EVENTS_PER_PAGE:usize=128;
static RECOVERY:Mutex<()>=Mutex::new(());
pub fn root()->PathBuf{std::env::var_os("TRACEFANG_QUANT_RESULTS_DIR").map(PathBuf::from).unwrap_or_else(||{
 if cfg!(target_os="windows"){if let Some(base)=std::env::var_os("LOCALAPPDATA"){return PathBuf::from(base).join("TraceFang/quant-results")}}
 let home=std::env::var_os("HOME").or_else(||std::env::var_os("USERPROFILE")).map(PathBuf::from).expect("persistent research directory requires user home or TRACEFANG_QUANT_RESULTS_DIR");
 if cfg!(target_os="macos"){home.join("Library/Application Support/TraceFang/quant-results")}
 else if cfg!(target_os="windows"){std::env::var_os("LOCALAPPDATA").map(PathBuf::from).unwrap_or_else(||home.join("AppData/Local")).join("TraceFang/quant-results")}
 else{std::env::var_os("XDG_DATA_HOME").map(PathBuf::from).unwrap_or_else(||home.join(".local/share")).join("tracefang/quant-results")}
})}
pub fn sync_directory(path:&Path)->Result<()>{#[cfg(unix)]fs::File::open(path)?.sync_all()?;Ok(())}
pub fn durability_scope()->&'static str{if cfg!(unix){"files and containing directories synchronized"}else{"files synchronized; rename atomicity follows platform filesystem"}}
pub fn create_directory(path:&Path)->Result<()>{if path.is_dir(){return Ok(());}let parent=path.parent().context("result directory has no parent")?;create_directory(parent)?;match fs::create_dir(path){Ok(())=>{},Err(e)if e.kind()==std::io::ErrorKind::AlreadyExists=>{},Err(e)=>return Err(e.into())}sync_directory(parent)}
pub fn atomic_json(path:&Path,value:&Value)->Result<()>{atomic_json_profile(path,value).map(|_|())}
pub fn atomic_json_profile(path:&Path,value:&Value)->Result<Value>{let temporary=path.with_extension(format!("pending-{}",uuid::Uuid::new_v4()));let mut writer=BufWriter::with_capacity(64*1024,fs::File::create(&temporary)?);let started=std::time::Instant::now();serde_json::to_writer(&mut writer,value)?;writer.flush()?;let write_us=started.elapsed().as_micros();let started=std::time::Instant::now();writer.get_ref().sync_all()?;let file_sync_us=started.elapsed().as_micros();let bytes=writer.get_ref().metadata()?.len();drop(writer);let started=std::time::Instant::now();fs::rename(&temporary,path)?;let rename_us=started.elapsed().as_micros();let started=std::time::Instant::now();sync_directory(path.parent().context("missing result directory")?)?;Ok(json!({"json_write_us":write_us.to_string(),"file_sync_us":file_sync_us.to_string(),"rename_us":rename_us.to_string(),"directory_sync_us":started.elapsed().as_micros().to_string(),"bytes":bytes.to_string()}))}
pub fn manifest(directory:&Path,active:bool)->Result<Value>{let _lock=RECOVERY.lock().expect("manifest recovery lock");let path=directory.join("manifest.json");let mut value:Value=serde_json::from_reader(fs::File::open(&path)?)?;
 if value["status"]=="running"&&!active{value["status"]=json!("interrupted");value["phase"]=json!("stopped");value["complete"]=json!(false);value["error"]=json!("服务重启中断计算；保留已发布的部分账本，不作为完整结果");value["interrupted_at"]=json!(chrono::Utc::now());atomic_json(&path,&value)?;}
 Ok(value)
}
pub fn write_canonical<T:Serialize>(writer:&mut BufWriter<fs::File>,hash:&mut Sha256,value:&T)->Result<()>{let bytes=serde_json::to_vec(value)?;writer.write_all(&bytes)?;writer.write_all(b"\n")?;hash.update(bytes);hash.update(b"\n");Ok(())}
pub struct EventWriter{pub directory:PathBuf,buffer:Vec<LedgerEvent>,pub pages:usize,pub events:u64,page_chain:Sha256}
impl EventWriter{
 pub fn new(directory:PathBuf)->Self{Self{directory,buffer:vec![],pages:0,events:0,page_chain:Sha256::new()}}
 pub fn push(&mut self,event:LedgerEvent)->Result<()>{self.buffer.push(event);self.events+=1;if self.buffer.len()==EVENTS_PER_PAGE{self.flush()?;}Ok(())}
 pub fn flush(&mut self)->Result<()>{if self.buffer.is_empty(){return Ok(());}let items=serde_json::to_value(&self.buffer)?;let hash=content_hash(&items)?;atomic_json(&self.directory.join(format!("events-{:08}.json",self.pages)),&json!({"page":self.pages,"items":items,"sha256":hash}))?;self.page_chain.update((self.pages as u64).to_be_bytes());self.page_chain.update(hash.as_bytes());self.pages+=1;self.buffer.clear();Ok(())}
 pub fn checksum(&self)->String{hex::encode(self.page_chain.clone().finalize())}
}
pub fn page(directory:&Path,index:usize)->Result<Value>{let mut value:Value=serde_json::from_slice(&fs::read(directory.join(format!("events-{index:08}.json")))?)?;if value.is_array(){return Ok(value);}ensure!(value["page"].as_u64()==Some(index as u64),"ledger page index differs");ensure!(value["items"].is_array(),"ledger page items missing");ensure!(value["sha256"]==content_hash(&value["items"])?,"ledger page checksum differs");Ok(value["items"].take())}
pub fn audit(directory:&Path,manifest:&Value)->Result<Value>{ensure!(manifest["complete"]==true&&manifest["status"]=="completed","only completed runs can be audited as complete");let mut input=fs::File::open(directory.join("canonical-input.jsonl"))?;let mut hash=Sha256::new();let mut buffer=[0u8;64*1024];let mut bytes=0u64;loop{let n=input.read(&mut buffer)?;if n==0{break;}bytes+=n as u64;hash.update(&buffer[..n]);}let input_hash=hex::encode(hash.finalize());ensure!(manifest["canonical_file_sha256"]==input_hash,"canonical input file checksum differs");ensure!(manifest["canonical_file_bytes"]==bytes.to_string(),"canonical input file length differs");
 let pages=manifest["event_pages"].as_u64().context("missing page count")?;let mut chain=Sha256::new();let mut count=0u64;for index in 0..pages{let items=page(directory,usize::try_from(index)?)?;count+=items.as_array().unwrap().len() as u64;chain.update(index.to_be_bytes());chain.update(content_hash(&items)?.as_bytes());}let page_hash=hex::encode(chain.finalize());ensure!(manifest["event_pages_sha256_chain"]==page_hash,"event page chain checksum differs");ensure!(manifest["event_count"]==count.to_string(),"event count differs");Ok(json!({"verified":true,"complete":true,"canonical_file_sha256":input_hash,"canonical_file_bytes":bytes.to_string(),"event_pages":pages,"event_count":count.to_string(),"event_pages_sha256_chain":page_hash}))
}
/// A completed run's source is immutable. Reconfiguration reads its exact file,
/// never today's live Store, and verifies the file and authority again at EOF.
pub fn saved_run_input(directory:&Path,manifest:&Value)->Result<super::quant::QuantInput>{
 audit(directory,manifest)?;let mut reader=BufReader::new(fs::File::open(directory.join("canonical-input.jsonl"))?);let mut line=Vec::new();reader.by_ref().take(16*1024*1024+1).read_until(b'\n',&mut line)?;ensure!(line.len()<=16*1024*1024,"saved input metadata exceeds bound");let value:Value=serde_json::from_slice(&line)?;let input:super::quant::QuantInput=serde_json::from_value(value["metadata"].clone())?;input.validate()?;ensure!(input.bars.is_empty(),"saved metadata contains inline bars");ensure!(serde_json::to_value(&input.token)?==manifest["snapshot_token"],"saved input token differs from run authority");Ok(input)
}
pub fn scan_saved_run<F,C>(directory:&Path,manifest:&Value,batch_rows:usize,cancel:C,mut accept:F)->Result<crate::persistence_contract::CanonicalScanSummary>where F:FnMut(super::quant::QuantInput)->Result<()>,C:Fn()->bool{
 use super::quant::*;
 ensure!(manifest["complete"]==true&&manifest["status"]=="completed","comparison requires a completed source run");ensure!((1..=4096).contains(&batch_rows),"saved input batch outside bounds");
 let mut reader=BufReader::new(fs::File::open(directory.join("canonical-input.jsonl"))?);let mut line=Vec::new();let mut bytes=0u64;let mut full_hash=Sha256::new();let mut row_hash=Sha256::new();reader.by_ref().take(16*1024*1024+1).read_until(b'\n',&mut line)?;ensure!(line.len()<=16*1024*1024,"saved input metadata exceeds bound");bytes+=line.len() as u64;full_hash.update(&line);let header:Value=serde_json::from_slice(&line)?;let template:QuantInput=serde_json::from_value(header["metadata"].clone())?;template.validate()?;ensure!(template.bars.is_empty()&&serde_json::to_value(&template.token)?==manifest["snapshot_token"],"saved input metadata differs from run authority");let config:super::simulation::SimulationConfig=serde_json::from_value(manifest["config"].clone())?;let mut prefix=PrefixHash::new(&template,&config.parameters)?;let mut batch=template.clone();let mut count=0u64;let mut previous=None;
 loop{ensure!(!cancel(),"cancelled");line.clear();reader.by_ref().take(1_048_577).read_until(b'\n',&mut line)?;if line.is_empty(){break;}ensure!(line.len()<=1_048_576,"saved canonical row exceeds bound");bytes+=line.len() as u64;full_hash.update(&line);row_hash.update(&line);let bar:QuantBar=serde_json::from_slice(&line)?;bar.validate()?;ensure!(previous.is_none_or(|at|bar.open_time>at),"saved input order differs");ensure!(bar.state=="final","saved simulation input contains preview");previous=Some(bar.open_time);prefix.push(&bar)?;batch.bars.push(bar);count+=1;if batch.bars.len()==batch_rows{accept(batch)?;batch=template.clone();}}
 ensure!(manifest["canonical_file_sha256"]==hex::encode(full_hash.finalize())&&manifest["canonical_file_bytes"]==bytes.to_string(),"saved canonical input checksum differs");ensure!(manifest["processed_bars"]==count.to_string(),"saved canonical input count differs");ensure!(prefix.finish(&template,template.decision_as_of,template.application_cursor)?.0==manifest["input_hash"],"saved canonical input differs from bound input version");if !batch.bars.is_empty()||count==0{accept(batch)?;}
 let mut summary:crate::persistence_contract::CanonicalScanSummary=serde_json::from_value(manifest["scan"].clone())?;summary.row_count=count;summary.sha256=hex::encode(row_hash.finalize());summary.complete=true;Ok(summary)
}
#[cfg(test)]mod tests{
 use super::*;
 #[test]fn buffered_atomic_json_keeps_identical_canonical_bytes(){let dir=tempfile::tempdir().unwrap();let value=json!({"wide":"1.0000000000000000000000000001","missing":null,"u64":"18446744073709551615","rows":(0..1000).map(|i|json!({"i":i,"exact":"-1e-256"})).collect::<Vec<_>>()});let path=dir.path().join("proof.json");atomic_json_profile(&path,&value).unwrap();assert_eq!(fs::read(path).unwrap(),serde_json::to_vec(&value).unwrap());}
 #[test]fn saved_input_reconfiguration_is_exact_and_rejects_tampered_authority(){
  use super::super::quant::*;use super::super::simulation::SimulationConfig;use super::super::exact::d;
  let dir=tempfile::tempdir().unwrap();let at:chrono::DateTime<chrono::Utc>="2024-01-01T00:00:00Z".parse().unwrap();let mut input:QuantInput=serde_json::from_value(json!({"code":"SIGNED","instrument":"SIGNED","name":"saved fixed oracle","unit":"test","executable_contract":false,"source_id":"fixed","period":"1m","decision_as_of":"2024-01-02T00:00:00Z","application_cursor":null,"token":{"store_epoch":"saved-fixed","commit_id":"7","schema_version":"fixed","aggregation_version":"fixed","projector_version":"fixed","committed_frame_seq":"0","catalog_version":"fixed","schedule_version":"fixed","route_version":"fixed"},"semantics":"final_revision_history","capabilities":[],"warmup_complete":false,"bars":[],"external_facts":[]})).unwrap();
  input.bars=(0..3).map(|i|QuantBar{open_time:at+chrono::Duration::minutes(i),bucket_end:at+chrono::Duration::minutes(i+1),open:d("-1.0000000000000000000000000001"),high:d("0"),low:d("-2"),close:d("-1"),volume:if i==0{None}else{Some(d("0"))},known_volume_sum:d("0"),known_volume_count:u64::from(i!=0),component_count:1,state:"final".into(),revision:1,observed_at:at,received_at:at,accepted_at:None,finalized_at:None,applied_frame_seq:None,source_precision_ns:Some(1),source_volume_components:None,source_volume_component_groups:Vec::new()}).collect();let mut metadata=input.clone();metadata.bars.clear();let config=SimulationConfig::default();let mut prefix=PrefixHash::new(&metadata,&config.parameters).unwrap();let mut file=BufWriter::new(fs::File::create(dir.path().join("canonical-input.jsonl")).unwrap());let mut digest=Sha256::new();write_canonical(&mut file,&mut digest,&json!({"metadata":metadata})).unwrap();for bar in &input.bars{prefix.push(bar).unwrap();write_canonical(&mut file,&mut digest,bar).unwrap();}file.flush().unwrap();let expected=prefix.finish(&metadata,metadata.decision_as_of,None).unwrap().0;
  let manifest=json!({"status":"completed","complete":true,"processed_bars":"3","config":config,"snapshot_token":metadata.token,"input_hash":expected,"canonical_file_sha256":hex::encode(digest.finalize()),"canonical_file_bytes":file.get_ref().metadata().unwrap().len().to_string(),"event_pages":0,"event_count":"0","event_pages_sha256_chain":hex::encode(Sha256::new().finalize()),"scan":{"version":{"store_epoch":"saved-fixed","commit_id":"7","committed_capture":null,"schema_version":"fixed","aggregation_version":"fixed","projector_version":"fixed","catalog_version":"fixed","schedule_version":"fixed","route_version":"fixed","active_generation":"fixed"},"row_count":"3","sha256":"fixed","complete":true}});
  saved_run_input(dir.path(),&manifest).unwrap();let mut seen=Vec::new();scan_saved_run(dir.path(),&manifest,2,||false,|batch|{seen.extend(batch.bars);Ok(())}).unwrap();assert_eq!(content_hash(&seen).unwrap(),content_hash(&input.bars).unwrap());assert!(seen[0].volume.is_none());assert_eq!(seen[1].volume,Some(d("0")));
  let mut changed=config.clone();changed.fee_rate=d("0.0003");assert_ne!(config.hash(&expected).unwrap(),changed.hash(&expected).unwrap());let mut wrong=manifest.clone();wrong["snapshot_token"]["commit_id"]=json!("8");assert!(scan_saved_run(dir.path(),&wrong,2,||false,|_|Ok(())).is_err());let mut wrong=manifest.clone();wrong["input_hash"]=json!("other-version");assert!(scan_saved_run(dir.path(),&wrong,2,||false,|_|Ok(())).is_err());let metadata_line=serde_json::to_vec(&json!({"metadata":metadata})).unwrap();let mut oversized=metadata_line;oversized.push(b'\n');oversized.extend(std::iter::repeat_n(b' ',1_048_577));fs::write(dir.path().join("canonical-input.jsonl"),oversized).unwrap();assert!(scan_saved_run(dir.path(),&manifest,2,||false,|_|Ok(())).unwrap_err().to_string().contains("row exceeds bound"));fs::write(dir.path().join("canonical-input.jsonl"),vec![b' ';16*1024*1024+1]).unwrap();assert!(scan_saved_run(dir.path(),&manifest,2,||false,|_|Ok(())).unwrap_err().to_string().contains("metadata exceeds bound"));fs::write(dir.path().join("canonical-input.jsonl"),b"changed").unwrap();assert!(saved_run_input(dir.path(),&manifest).is_err());
 }
 #[test]fn restarted_running_job_is_interrupted_once_under_concurrent_reads(){let dir=tempfile::tempdir().unwrap();atomic_json(&dir.path().join("manifest.json"),&json!({"status":"running","complete":false,"processed_bars":"256","event_pages":2})).unwrap();let threads:Vec<_>=(0..8).map(|_|{let path=dir.path().to_path_buf();std::thread::spawn(move||manifest(&path,false).unwrap())}).collect();let values:Vec<_>=threads.into_iter().map(|t|t.join().unwrap()).collect();for value in &values{assert_eq!(value["status"],"interrupted");assert_eq!(value["processed_bars"],"256");assert_eq!(value["event_pages"],2);assert_eq!(value["interrupted_at"],values[0]["interrupted_at"]);}assert_eq!(fs::read_dir(dir.path()).unwrap().count(),1);}
 #[test]fn complete_evidence_audit_detects_input_and_page_corruption(){let dir=tempfile::tempdir().unwrap();let bytes=b"{\"exact\":\"100.0000000000000000000001\"}\n";fs::write(dir.path().join("canonical-input.jsonl"),bytes).unwrap();let items=json!([]);let page_hash=content_hash(&items).unwrap();atomic_json(&dir.path().join("events-00000000.json"),&json!({"page":0,"items":items,"sha256":page_hash})).unwrap();let mut chain=Sha256::new();chain.update(0u64.to_be_bytes());chain.update(page_hash.as_bytes());let m=json!({"complete":true,"status":"completed","canonical_file_sha256":hex::encode(Sha256::digest(bytes)),"canonical_file_bytes":bytes.len().to_string(),"event_pages":1,"event_count":"0","event_pages_sha256_chain":hex::encode(chain.finalize())});assert_eq!(audit(dir.path(),&m).unwrap()["verified"],true);fs::write(dir.path().join("canonical-input.jsonl"),b"corrupt").unwrap();assert!(audit(dir.path(),&m).is_err());fs::write(dir.path().join("canonical-input.jsonl"),bytes).unwrap();atomic_json(&dir.path().join("events-00000000.json"),&json!({"page":0,"items":[1],"sha256":page_hash})).unwrap();assert!(audit(dir.path(),&m).is_err());}
}
